$utf8 = [System.Text.UTF8Encoding]::new($false)

function Write-LevelFile {
    param(
        [string]$Path,
        [string]$Content
    )

    $full = Join-Path $PWD $Path
    $dir = Split-Path $full -Parent

    if (!(Test-Path $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }

    [System.IO.File]::WriteAllText(
        $full,
        $Content,
        $utf8
    )
}

