Write-LevelFile "src\pages\DashboardPage.tsx" @'
import {
  BriefcaseBusiness,
  Calculator,
  ChevronLeft,
  ChevronRight,
  FileSignature,
  FileText,
  Plus,
} from 'lucide-react'

import {
  useEffect,
  useState,
} from 'react'

import {
  Link,
} from 'react-router-dom'

import {
  supabase,
} from '../lib/supabase'

type BannerRow = {
  id: string
  title: string
  image_url: string
  link_url: string | null
  sort_order: number
}

export function DashboardPage() {
  const [
    cases,
    setCases,
  ] = useState(0)

  const [
    documents,
    setDocuments,
  ] = useState(0)

  const [
    requests,
    setRequests,
  ] = useState(0)

  const [
    banners,
    setBanners,
  ] = useState<BannerRow[]>([])

  const [
    activeBanner,
    setActiveBanner,
  ] = useState(0)

  useEffect(() => {
    void Promise.all([
      supabase
        .from('adv_cases')
        .select(
          'id',
          {
            count: 'exact',
            head: true,
          }
        ),

      supabase
        .from('adv_documents')
        .select(
          'id',
          {
            count: 'exact',
            head: true,
          }
        ),

      supabase
        .from(
          'adv_analysis_requests'
        )
        .select(
          'id',
          {
            count: 'exact',
            head: true,
          }
        ),

      supabase
        .from('adv_banners')
        .select(
          'id,title,image_url,link_url,sort_order'
        )
        .eq(
          'is_active',
          true
        )
        .order(
          'sort_order',
          {
            ascending: true,
          }
        ),
    ]).then(
      ([
        caseResult,
        documentResult,
        requestResult,
        bannerResult,
      ]) => {
        setCases(
          caseResult.count ?? 0
        )

        setDocuments(
          documentResult.count ?? 0
        )

        setRequests(
          requestResult.count ?? 0
        )

        if (!bannerResult.error) {
          setBanners(
            (bannerResult.data ?? [])
            as BannerRow[]
          )
        }
      }
    )
  }, [])

  useEffect(() => {
    if (
      banners.length <= 1
    ) {
      return
    }

    const timer =
      window.setInterval(
        () => {
          setActiveBanner(
            (current) =>
              (
                current + 1
              ) %
              banners.length
          )
        },
        7000
      )

    return () =>
      window.clearInterval(
        timer
      )
  }, [banners.length])

  useEffect(() => {
    if (
      activeBanner >=
      banners.length
    ) {
      setActiveBanner(0)
    }
  }, [
    activeBanner,
    banners.length,
  ])

  function previousBanner() {
    if (
      banners.length === 0
    ) {
      return
    }

    setActiveBanner(
      (current) =>
        (
          current -
          1 +
          banners.length
        ) %
        banners.length
    )
  }

  function nextBanner() {
    if (
      banners.length === 0
    ) {
      return
    }

    setActiveBanner(
      (current) =>
        (
          current + 1
        ) %
        banners.length
    )
  }

  const banner =
    banners[
      activeBanner
    ]

  return (
    <div className="page">
      {banner && (
        <section className="adv-banner-carousel">
          {banner.link_url ? (
            banner.link_url
              .startsWith('/') ? (
              <Link
                className="adv-banner-link"
                to={
                  banner.link_url
                }
                aria-label={
                  banner.title
                }
              >
                <img
                  src={
                    banner.image_url
                  }
                  alt={
                    banner.title
                  }
                />
              </Link>
            ) : (
              <a
                className="adv-banner-link"
                href={
                  banner.link_url
                }
                target="_blank"
                rel="noreferrer"
                aria-label={
                  banner.title
                }
              >
                <img
                  src={
                    banner.image_url
                  }
                  alt={
                    banner.title
                  }
                />
              </a>
            )
          ) : (
            <img
              src={
                banner.image_url
              }
              alt={
                banner.title
              }
            />
          )}

          {banners.length > 1 && (
            <>
              <button
                type="button"
                className="banner-arrow previous"
                onClick={
                  previousBanner
                }
                aria-label="Banner anterior"
              >
                <ChevronLeft
                  size={20}
                />
              </button>

              <button
                type="button"
                className="banner-arrow next"
                onClick={
                  nextBanner
                }
                aria-label="Próximo banner"
              >
                <ChevronRight
                  size={20}
                />
              </button>

              <div className="banner-dots">
                {banners.map(
                  (
                    item,
                    index
                  ) => (
                    <button
                      key={
                        item.id
                      }
                      type="button"
                      className={
                        index ===
                        activeBanner
                          ? 'active'
                          : ''
                      }
                      onClick={() =>
                        setActiveBanner(
                          index
                        )
                      }
                      aria-label={
                        `Abrir banner ${index + 1}`
                      }
                    />
                  )
                )}
              </div>
            </>
          )}
        </section>
      )}

      <section className="stats-grid">
        <article>
          <BriefcaseBusiness
            size={20}
          />

          <span>Casos</span>
          <strong>{cases}</strong>
        </article>

        <article>
          <FileText size={20} />

          <span>Documentos</span>
          <strong>
            {documents}
          </strong>
        </article>

        <article>
          <Calculator size={20} />

          <span>
            Análises solicitadas
          </span>

          <strong>
            {requests}
          </strong>
        </article>

        <article className="gold-stat">
          <Plus size={20} />

          <span>
            Ferramentas LEVEL
          </span>

          <strong>
            ADV
          </strong>
        </article>
      </section>

      <section className="dashboard-grid">
        <article className="panel">
          <span className="eyebrow">
            CALCULADORAS
          </span>

          <h2>
            Ferramentas jurídicas
            em um só ambiente
          </h2>

          <p>
            Acesse calculadoras bancárias,
            trabalhistas, tributárias,
            previdenciárias e outras
            ferramentas de apoio.
          </p>

          <Link
            to="/app/calculadoras"
            className="text-link"
          >
            Abrir calculadoras →
          </Link>
        </article>

        <article className="panel">
          <span className="eyebrow">
            DOCUMENTOS
          </span>

          <h2>
            Modelos prontos
            para editar
          </h2>

          <p>
            Use os geradores jurídicos,
            salve seus documentos e
            gere PDFs diretamente
            pela plataforma.
          </p>

          <Link
            to="/app/gerador-documentos"
            className="text-link"
          >
            Abrir gerador →
          </Link>
        </article>

        <article className="panel">
          <span className="eyebrow">
            CASOS
          </span>

          <h2>
            Organize o histórico
            dos seus clientes
          </h2>

          <p>
            Centralize cálculos,
            documentos, contribuições
            e andamento dos casos.
          </p>

          <Link
            to="/app/casos"
            className="text-link"
          >
            Abrir casos →
          </Link>
        </article>

        <article className="panel">
          <span className="eyebrow">
            LEVEL ADV
          </span>

          <h2>
            Uma empresa
            Ludo Digital MKT
          </h2>

          <p>
            Tecnologia criada para
            apoiar a rotina jurídica,
            centralizar ferramentas e
            melhorar a produtividade
            das equipes.
          </p>

          <FileSignature
            size={28}
          />
        </article>
      </section>
    </div>
  )
}

'@

# ============================================================
# 4. PAINEL DE BANNERS
# ============================================================

Write-LevelFile "src\pages\BannerAdminPage.tsx" @'
import {
  Eye,
  EyeOff,
  ImagePlus,
  Save,
  Trash2,
  UploadCloud,
} from 'lucide-react'

import {
  useEffect,
  useState,
} from 'react'

import type {
  ChangeEvent,
} from 'react'

import {
  useAuth,
} from '../context/AuthContext'

import {
  supabase,
} from '../lib/supabase'

type BannerRow = {
  id: string
  title: string
  image_url: string
  storage_path: string | null
  link_url: string | null
  sort_order: number
  is_active: boolean
  created_at: string
}

function safeName(
  value: string
) {
  return value
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    )
    .replace(
      /[^a-zA-Z0-9._-]/g,
      '-'
    )
}

export function BannerAdminPage() {
  const {
    user,
    isAdmin,
  } =
    useAuth()

  const [
    banners,
    setBanners,
  ] =
    useState<BannerRow[]>([])

  const [
    file,
    setFile,
  ] =
    useState<File | null>(
      null
    )

  const [
    title,
    setTitle,
  ] =
    useState('')

  const [
    linkUrl,
    setLinkUrl,
  ] =
    useState('/app')

  const [
    sortOrder,
    setSortOrder,
  ] =
    useState(10)

  const [
    message,
    setMessage,
  ] =
    useState('')

  const [
    busy,
    setBusy,
  ] =
    useState(false)

  async function load() {
    if (!isAdmin) {
      return
    }

    const {
      data,
      error,
    } =
      await supabase
        .from('adv_banners')
        .select('*')
        .order(
          'sort_order',
          {
            ascending: true,
          }
        )

    if (error) {
      setMessage(
        error.message
      )

      return
    }

    setBanners(
      (data ?? [])
      as BannerRow[]
    )
  }

  useEffect(() => {
    void load()
  }, [isAdmin])

  function onFile(
    event:
      ChangeEvent<HTMLInputElement>
  ) {
    const next =
      event.target.files?.[0] ??
      null

    if (!next) {
      setFile(null)
      return
    }

    if (
      !next.type
        .startsWith('image/')
    ) {
      setMessage(
        'Selecione uma imagem PNG, JPG ou WEBP.'
      )

      event.target.value = ''
      return
    }

    if (
      next.size >
      8 * 1024 * 1024
    ) {
      setMessage(
        'A imagem deve ter no máximo 8 MB.'
      )

      event.target.value = ''
      return
    }

    setMessage('')
    setFile(next)
  }

  async function createBanner() {
    if (
      !user ||
      !isAdmin
    ) {
      return
    }

    if (
      !file ||
      !title.trim()
    ) {
      setMessage(
        'Informe o título e selecione a imagem.'
      )

      return
    }

    setBusy(true)
    setMessage(
      'Enviando banner...'
    )

    const storagePath =
      `${user.id}/${Date.now()}-${safeName(file.name)}`

    const {
      error: uploadError,
    } =
      await supabase.storage
        .from(
          'level-adv-banners'
        )
        .upload(
          storagePath,
          file,
          {
            contentType:
              file.type,
            upsert: false,
          }
        )

    if (uploadError) {
      setBusy(false)
      setMessage(
        uploadError.message
      )
      return
    }

    const {
      data: publicUrl,
    } =
      supabase.storage
        .from(
          'level-adv-banners'
        )
        .getPublicUrl(
          storagePath
        )

    const {
      error,
    } =
      await supabase
        .from('adv_banners')
        .insert({
          title:
            title.trim(),

          image_url:
            publicUrl.publicUrl,

          storage_path:
            storagePath,

          link_url:
            linkUrl.trim() ||
            null,

          sort_order:
            sortOrder,

          is_active:
            true,

          created_by:
            user.id,
        })

    if (error) {
      await supabase.storage
        .from(
          'level-adv-banners'
        )
        .remove([
          storagePath,
        ])

      setBusy(false)
      setMessage(
        error.message
      )
      return
    }

    setTitle('')
    setLinkUrl('/app')
    setSortOrder(10)
    setFile(null)
    setBusy(false)
    setMessage(
      'Banner publicado no carrossel.'
    )

    await load()
  }

  function updateLocal(
    id: string,
    patch:
      Partial<BannerRow>
  ) {
    setBanners(
      (current) =>
        current.map(
          (item) =>
            item.id === id
              ? {
                  ...item,
                  ...patch,
                }
              : item
        )
    )
  }

  async function saveBanner(
    banner: BannerRow
  ) {
    setBusy(true)

    const {
      error,
    } =
      await supabase
        .from('adv_banners')
        .update({
          title:
            banner.title.trim(),

          link_url:
            banner.link_url
              ?.trim() ||
            null,

          sort_order:
            Number(
              banner.sort_order
            ) || 0,

          is_active:
            banner.is_active,
        })
        .eq(
          'id',
          banner.id
        )

    setBusy(false)

    if (error) {
      setMessage(
        error.message
      )
      return
    }

    setMessage(
      'Banner atualizado.'
    )

    await load()
  }

  async function toggleBanner(
    banner: BannerRow
  ) {
    const {
      error,
    } =
      await supabase
        .from('adv_banners')
        .update({
          is_active:
            !banner.is_active,
        })
        .eq(
          'id',
          banner.id
        )

    if (error) {
      setMessage(
        error.message
      )
      return
    }

    await load()
  }

  async function deleteBanner(
    banner: BannerRow
  ) {
    const confirmed =
      window.confirm(
        `Excluir o banner "${banner.title}"?`
      )

    if (!confirmed) {
      return
    }

    setBusy(true)

    if (
      banner.storage_path
    ) {
      const {
        error:
          storageError,
      } =
        await supabase.storage
          .from(
            'level-adv-banners'
          )
          .remove([
            banner.storage_path,
          ])

      if (storageError) {
        setBusy(false)
        setMessage(
          storageError.message
        )
        return
      }
    }

    const {
      error,
    } =
      await supabase
        .from('adv_banners')
        .delete()
        .eq(
          'id',
          banner.id
        )

    setBusy(false)

    if (error) {
      setMessage(
        error.message
      )
      return
    }

    setMessage(
      'Banner excluído.'
    )

    await load()
  }

  if (!isAdmin) {
    return (
      <div className="page">
        <div className="module-coming">
          Acesso restrito.
        </div>
      </div>
    )
  }

  return (
    <div className="page banner-admin-page">
      <div className="page-heading">
        <span className="eyebrow">
          ADMINISTRAÇÃO
        </span>

        <h1>
          Banners e anúncios
        </h1>

        <p>
          Adicione imagens ao carrossel
          da página inicial, defina
          ordem, destino do clique e
          ative ou pause cada banner.
        </p>
      </div>

      {message && (
        <div className="system-message">
          {message}
        </div>
      )}

      <section className="panel banner-create-panel">
        <div className="panel-heading">
          <div>
            <span className="eyebrow">
              NOVO BANNER
            </span>

            <h2>
              Publicar imagem
            </h2>

            <p>
              Recomendado: 1600 × 900
              ou 1920 × 1080, formato
              16:9, PNG/JPG/WEBP.
            </p>
          </div>

          <ImagePlus size={24} />
        </div>

        <div className="banner-admin-form">
          <label>
            Título interno

            <input
              value={title}
              onChange={(event) =>
                setTitle(
                  event.target.value
                )
              }
              placeholder="Ex.: Calculadoras jurídicas"
            />
          </label>

          <label>
            Link ao clicar

            <input
              value={linkUrl}
              onChange={(event) =>
                setLinkUrl(
                  event.target.value
                )
              }
              placeholder="/app/calculadoras ou https://..."
            />
          </label>

          <label>
            Ordem

            <input
              type="number"
              value={sortOrder}
              onChange={(event) =>
                setSortOrder(
                  Number(
                    event.target.value
                  )
                )
              }
            />
          </label>

          <label className="banner-upload-field">
            <UploadCloud
              size={24}
            />

            <strong>
              Selecionar imagem
            </strong>

            <span>
              {file
                ? file.name
                : 'PNG, JPG ou WEBP • até 8 MB'}
            </span>

            <input
              type="file"
              accept="image/png,image/jpeg,image/webp"
              onChange={onFile}
            />
          </label>
        </div>

        <button
          type="button"
          className="primary-button"
          onClick={() =>
            void createBanner()
          }
          disabled={busy}
        >
          <UploadCloud
            size={15}
          />

          {busy
            ? 'Salvando...'
            : 'Salvar no carrossel'}
        </button>
      </section>

      <section className="banner-admin-list">
        {banners.map(
          (banner) => (
            <article
              key={banner.id}
              className="banner-admin-card"
            >
              <img
                src={
                  banner.image_url
                }
                alt={
                  banner.title
                }
              />

              <div className="banner-admin-card-body">
                <label>
                  Título

                  <input
                    value={
                      banner.title
                    }
                    onChange={(event) =>
                      updateLocal(
                        banner.id,
                        {
                          title:
                            event
                              .target
                              .value,
                        }
                      )
                    }
                  />
                </label>

                <label>
                  Link

                  <input
                    value={
                      banner.link_url ??
                      ''
                    }
                    onChange={(event) =>
                      updateLocal(
                        banner.id,
                        {
                          link_url:
                            event
                              .target
                              .value,
                        }
                      )
                    }
                  />
                </label>

                <label>
                  Ordem

                  <input
                    type="number"
                    value={
                      banner.sort_order
                    }
                    onChange={(event) =>
                      updateLocal(
                        banner.id,
                        {
                          sort_order:
                            Number(
                              event
                                .target
                                .value
                            ),
                        }
                      )
                    }
                  />
                </label>

                <div className="banner-admin-actions">
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={() =>
                      void toggleBanner(
                        banner
                      )
                    }
                  >
                    {banner.is_active ? (
                      <EyeOff
                        size={14}
                      />
                    ) : (
                      <Eye
                        size={14}
                      />
                    )}

                    {banner.is_active
                      ? 'Pausar'
                      : 'Ativar'}
                  </button>

                  <button
                    type="button"
                    className="secondary-button"
                    onClick={() =>
                      void saveBanner(
                        banner
                      )
                    }
                    disabled={busy}
                  >
                    <Save
                      size={14}
                    />

                    Salvar
                  </button>

                  <button
                    type="button"
                    className="secondary-button danger"
                    onClick={() =>
                      void deleteBanner(
                        banner
                      )
                    }
                    disabled={busy}
                  >
                    <Trash2
                      size={14}
                    />

                    Excluir
                  </button>
                </div>
              </div>
            </article>
          )
        )}
      </section>
    </div>
  )
}

'@

# ============================================================
# 5. MIGRATION BANNERS
# ============================================================

$migrationPath = ".\supabase\migrations\20260921224500_branding_banners_v12.sql"

if (!(Test-Path $migrationPath)) {
    Write-LevelFile "supabase\migrations\20260921224500_branding_banners_v12.sql" @'
-- LEVEL ADV V12 - BRANDING + BANNERS

create table if not exists public.adv_banners (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  image_url text not null,
  storage_path text,
  link_url text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_by uuid
    references public.profiles(id)
    on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists
adv_banners_active_order_idx
on public.adv_banners(
  is_active,
  sort_order,
  created_at
);

alter table public.adv_banners
enable row level security;

drop policy if exists
"adv_banners_select"
on public.adv_banners;

create policy
"adv_banners_select"
on public.adv_banners
for select
to authenticated
using (true);

drop policy if exists
"adv_banners_insert"
on public.adv_banners;

create policy
"adv_banners_insert"
on public.adv_banners
for insert
to authenticated
with check (
  public.is_admin()
);

drop policy if exists
"adv_banners_update"
on public.adv_banners;

create policy
"adv_banners_update"
on public.adv_banners
for update
to authenticated
using (
  public.is_admin()
)
with check (
  public.is_admin()
);

drop policy if exists
"adv_banners_delete"
on public.adv_banners;

create policy
"adv_banners_delete"
on public.adv_banners
for delete
to authenticated
using (
  public.is_admin()
);

create or replace function
public.level_adv_banner_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists
level_adv_banner_updated_at
on public.adv_banners;

create trigger
level_adv_banner_updated_at
before update
on public.adv_banners
for each row
execute function
public.level_adv_banner_updated_at();

insert into storage.buckets (
  id,
  name,
  public,
  file_size_limit,
  allowed_mime_types
)
values (
  'level-adv-banners',
  'level-adv-banners',
  true,
  8388608,
  array[
    'image/jpeg',
    'image/png',
    'image/webp'
  ]
)
on conflict (id)
do update set
  public = true,
  file_size_limit = 8388608,
  allowed_mime_types =
    excluded.allowed_mime_types;

drop policy if exists
"level_adv_banners_insert"
on storage.objects;

create policy
"level_adv_banners_insert"
on storage.objects
for insert
to authenticated
with check (
  bucket_id =
    'level-adv-banners'
  and public.is_admin()
);

drop policy if exists
"level_adv_banners_update"
on storage.objects;

create policy
"level_adv_banners_update"
on storage.objects
for update
to authenticated
using (
  bucket_id =
    'level-adv-banners'
  and public.is_admin()
)
with check (
  bucket_id =
    'level-adv-banners'
  and public.is_admin()
);

drop policy if exists
"level_adv_banners_delete"
on storage.objects;

create policy
"level_adv_banners_delete"
on storage.objects
for delete
to authenticated
using (
  bucket_id =
    'level-adv-banners'
  and public.is_admin()
);

insert into public.adv_banners (
  title,
  image_url,
  link_url,
  sort_order,
  is_active
)
values
  (
    'Calculadoras jurídicas inteligentes',
    '/brand/banners/banner-calculadoras.webp',
    '/app/calculadoras',
    1,
    true
  ),
  (
    'Geradores de documentos',
    '/brand/banners/banner-documentos.webp',
    '/app/gerador-documentos',
    2,
    true
  ),
  (
    'Casos, equipe e colaboração',
    '/brand/banners/banner-casos.webp',
    '/app/casos',
    3,
    true
  ),
  (
    'Segurança, LGPD e controle',
    '/brand/banners/banner-lgpd.webp',
    '/app',
    4,
    true
  );

'@
}

